namespace CosmicTranscriber.Utilities;
internal static class DiagnosticVocabulary
{
    private static readonly HashSet<string> LegacyCategories = new(new[] { "DIAGNOSTICS", "ABOUT", "CLIPBOARD", "ACTIVITY", "API KEY", "API KEY LOAD FALLBACK", "API KEY VAULT PRESENCE UNKNOWN", "API KEY VAULT UNREADABLE", "Authentication", "CLEAR ELEVATION COMPATIBILITY", "COMPLETION", "COMPLETION OPEN OUTPUT", "Checkpoint", "Cleanup", "ConnectionTest", "ELEVATION", "ELEVATION COMPATIBILITY CHECK", "Export", "FATAL STARTUP", "LIFECYCLE", "MAINWINDOW", "NATIVE_TEST", "OPENAI API", "OPENAI CONNECTION TEST", "OPENAI_HTTP", "OPERATION", "OUTPUT PATH FALLBACK", "OutputDirectory", "SETTINGS", "SETTINGS DIRECTORY", "SETTINGS DIRECTORY REJECTED", "SETTINGS FALLBACK", "SETTINGS SAVE", "SETTINGS TEMP FALLBACK", "SOCKET_TEST", "STARTUP", "Settings", "Startup", "TEST", "THEME", "TRANSCRIPTION FILE FAILURE", "TRANSCRIPTION RUN FAILURE", "Transcription", "UI_FOCUS", "UI_VISIBILITY", "UNELEVATED RELAUNCH", "UNHANDLED APPDOMAIN", "UNHANDLED DISPATCHER", "UNOBSERVED TASK", "WINDOW" }, StringComparer.Ordinal);
    private static readonly HashSet<string> WireCategories = new(LegacyCategories.Select(x => x.Replace(' ', '_')), StringComparer.Ordinal);
    internal static string Category(string? value)
    {
        if (value is null) return "OTHER";
        if (Enum.TryParse<DiagnosticArea>(value, out var area) && Enum.IsDefined(area) && area.ToString() == value) return value;
        if (LegacyCategories.Contains(value)) return value.Replace(' ', '_');
        return WireCategories.Contains(value) ? value : "OTHER";
    }
    internal static bool IsWireCategory(string? value) => value is not null && value != "OTHER" && Category(value) == value;

    internal static string Control(string? value) => value is "ExportSupportButton" or "ReviewUncertainButton" or "AboutButton" or "ApiKeyRevealTextBox" or "ApiKeySettingsCard" or "ApiKeyShortcutButton" or "ApiKeySourceText" or "ApiPasswordBox" or "CancelButton" or "ChunkDurationSlider" or "ChunkDurationText" or "ChunkSizeSlider" or "ChunkSizeText" or "CombinedTitleTextBox" or "ContinueOnErrorCheckBox" or "CostBadgeText" or "CurrentActionText" or "DragDropWarningBanner" or "DragDropWarningDetailText" or "DragDropWarningTitleText" or "DropZoneGrid" or "DropZoneHelpText" or "DropZoneIconText" or "DropZoneRectangle" or "DropZoneTitleText" or "EstimateText" or "ExportMarkdownCheckBox" or "ExportTextCheckBox" or "FilesListView" or "FooterDetailText" or "FooterProgressBar" or "FooterTitleText" or "HeaderStatusText" or "HeaderVersionText" or "IncludeTimestampsCheckBox" or "ItemCard" or "KeywordSupportText" or "KeywordsTextBox" or "LanguageTextBox" or "LogTextBox" or "MergeFilesCheckBox" or "ModelCapabilityText" or "ModelComboBox" or "OpenDiagnosticLogsButton" or "OutputPathTextBox" or "OutputSettingsCard" or "OverallProgressBar" or "PreviousContextCheckBox" or "PricePerMinuteTextBox" or "ProgressPercentText" or "PromptResetButton" or "PromptTextBox" or "QueueActionPanel" or "QueueCard" or "QueueSummaryText" or "RememberKeyCheckBox" or "RestartNormallyButton" or "RetryComboBox" or "RevealKeyButton" or "RootDropSurface" or "SettingsAutoSaveStatusText" or "SettingsViewport" or "StartButton" or "TestKeyButton" or "ThemeToggleButton" or "TranscriptionSettingsCard" or "WorkspaceCanvas" or "WorkspaceViewport" or "unnamed" ? value : "other";
    internal static string Type(string? value) => value is "TextBox" or "PasswordBox" or "Button" or "CheckBox" or "ComboBox" or "ComboBoxItem" or "ScrollViewer" or "Expander" or "Window" ? value : "other";
    internal static string ViewportStage(string? value) => value is "handler_enter" or "scheduled" or "post_render" or "stable_visible" or "stable_unresolved" or "render_detached" or "cancelled" or "complete" or "logical_scroll_skipped" or "template_missing" or "before" or "requested" or "settled" or "detached" ? value : "other";
    internal static string WindowStage(string? value) => value is "main_window_shown" or "loaded" or "activated" or "deactivated" or "state_changed" ? value : "other";
    internal static string Lifecycle(string? value) => value is "constructor_entered" or "resources_loading" or "main_window_constructing" or "window_showing" or "unhandled_non_exception" or "shift_tab_navigation" or "tab_navigation" or "concurrent_event" ? value : "other";
}
